import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testUnsorted() {
        Assert.assertEquals(listOf(12, 22, 25, 34, 64), bubbleSort(mutableListOf(64, 34, 25, 12, 22)))
    }

    @Test
    fun testAlreadySorted() {
        Assert.assertEquals(listOf(1, 2, 3), bubbleSort(mutableListOf(1, 2, 3)))
    }

    @Test
    fun testReversed() {
        Assert.assertEquals(listOf(1, 2, 3, 4), bubbleSort(mutableListOf(4, 3, 2, 1)))
    }

    @Test
    fun testSingleElement() {
        Assert.assertEquals(listOf(42), bubbleSort(mutableListOf(42)))
    }
}
